'use strict';
const fs=require('node:fs'),path=require('node:path');
const root=path.resolve(__dirname,'..');
const demo=JSON.parse(fs.readFileSync(path.join(root,'metrics_demo_2_stimoli.json'),'utf8'));
const sources={};
for(const {file}of Object.values(demo.demo_info.videos)){
  if(!/^video_demo_[a-z_]+\.mp4$/.test(file))throw new Error('Nome video dimostrativo non valido.');
  sources[file]='data:video/mp4;base64,'+fs.readFileSync(path.join(root,file)).toString('base64');
}
fs.writeFileSync(path.join(root,'js/demo-videos.js'),
  '/* Generated by scripts/build-demo-videos.cjs from the bundled MP4 files. */\n'+
  '(function(root){root.MetricsDemoVideoData=Object.freeze('+JSON.stringify(sources)+');})(globalThis);\n');
console.log('Bundled '+Object.keys(sources).length+' demo videos for local-file exports.');
